  3→import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";
  4→
  5→const corsHeaders = {
  6→  "Access-Control-Allow-Origin": "*",
  7→  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  8→};
  9→
 10→interface SendEmailRequest {
 11→  to: string;
 12→  template_key: string;
 13→  variables: Record<string, string>;
 14→}
 15→
 16→/** Replace {{variable}} placeholders in a template string */
 17→function renderTemplate(template: string, variables: Record<string, string>): string {
 18→  return template.replace(/\{\{(\w+)\}\}/g, (_, key) => variables[key] ?? "");
 19→}
